        const artefactData = {
          title: document.getElementById('artefact-title').value,
          description: document.getElementById('artefact-description').value,
          url: document.getElementById('artefact-url').value,
          visibility: document.getElementById('artefact-visibility').value // Added line
        };

        fetch('/api/artefacts', {
